CREATE TABLE tools (id TEXT PRIMARY KEY, name TEXT NOT NULL, state TEXT NOT NULL);
CREATE TABLE members (id TEXT PRIMARY KEY, display_name TEXT NOT NULL, safety_briefing_at TEXT, suspended INTEGER NOT NULL DEFAULT 0);
CREATE TABLE rentals (id TEXT PRIMARY KEY, tool_id TEXT NOT NULL REFERENCES tools(id), member_id TEXT NOT NULL REFERENCES members(id), state TEXT NOT NULL, opened_at TEXT NOT NULL, closed_at TEXT);
CREATE TABLE events (id INTEGER PRIMARY KEY AUTOINCREMENT, type TEXT NOT NULL, ref TEXT NOT NULL);
